def error_formulation():
    def e(path, title, host, scen, inp, ret, behav, ref, basis, metric=ERR, scenario=None, step=3):
        test(P + "/error-formulation/" + path, title, [
            ("Сценарий", scen),
            ("Контекст агента " + host, agent_ctx(host)),
            ("Вход", inp + "\n\n" + ret),
            ("Ожидаемое поведение", behav),
            ("Эталон", ref),
            ("Метрики", metric),
            ("Основания", basis),
            ("Данные", "Контекст агента, запрос, ошибка ручки (enum с описанием), эталонная суть ошибки, рубрика judge."),
        ], scenario=scenario, step=step)

    e("01-ssh-key-rejected", "local/error-formulation/01 — не подходит ssh-ключ", "srv-1c",
      "Пункт плана MR-6 на уровне агента; путь ошибки «не подходит ssh-ключ» [M] = `ssh-refused` с текстом «Permission denied (publickey)» [AR-25]. Агент эскалирует оркестратору — пользователю сообщает оркестратор [UC-27].",
      task("Заполненность всех томов и прогноз, когда закончится место", "посмотри заполненность дисков на сервере с 1С"), F.ERR_SSHKEY,
      """- `escalate(error)`: данные не получены — сервер на связи, но не принял ключ доступа (2 попытки).
- Возможные причины (ключ удалён с сервера, изменена учётка) — явно как предположения.
- Ошибки: «сервер недоступен» или «выключен»; данные по дискам из описания; `answer` вместо эскалации (оркестратор должен сообщить пользователю); повтор ручки сверх попыток.""",
      "- Терминальная ручка: `escalate(error)`; суть: ключ отклонён сервером; сервер отвечает.",
      "[AR-25] — при `ssh-refused` эскалация оркестратору; 2 попытки с паузой 5 с внутри ручки [AR-42]; [M]; [K §2.2] «Сервер не отвечает».", scenario="MR-6", step=3)

    e("02-log-access-lost", "local/error-formulation/02 — пропал доступ к журналу", "web-01",
      "Путь ошибки «пропал доступ к логу» [M] = `source-unavailable` `[предл.]` [AR-25]: ручка не может прочитать файл логгера на хосте. Не `ssh-refused` — сервер доступен, но данных за окно нет; агент сообщает это оркестратору и не выдаёт ноль. Случай «логгер перестал писать» — не ошибка, а предупреждение вместе с результатом (design doc 4.1, 5.4) — handle-choice/14.",
      task("Сколько ошибок было у сайта за ночь", "сколько ошибок было у сайта за ночь?"), F.ERR_LOG,
      """- `escalate(error)` (или `answer` — засчитывается): данных об ошибках веб-сервера за ночь нет — файл логгера на web-01 не читается (Permission denied); сервер при этом доступен.
- Не «ошибок 0» и не «nginx не работает».
- Предположения сверх описания ошибки (например, что права меняли при обновлении) — только явно как предположения или не высказываются.
- Ошибки: число ошибок за ночь; «сервер недоступен»; подмена задачи выборкой access-лога без пометки, что данные журнала ошибок не прочитаны.""",
      "- Суть ошибки: нет доступа к файлу логгера ошибок веб-сервера; данных за окно нет; сервер доступен.",
      "[AR-25]; [M]; что видит пользователь — [Q42].", scenario="MR-6b", step=3)

    e("03-connection-timeout", "local/error-formulation/03 — сервер не ответил", "srv-1c",
      "Пункт плана MR-6 на уровне агента: `ssh-refused` после 2 попыток с паузой 5 с (таймаут) [AR-42] — эскалация оркестратору с возможными причинами из описания ошибки.",
      task("Заполненность всех томов и прогноз, когда закончится место", "посмотри заполненность дисков на сервере с 1С"), F.ERR_TIMEOUT,
      """- `escalate(error)`: srv-1c не ответил по SSH после 2 попыток; возможные причины — выключен, изменён allow-list, сменился адрес.
- Ошибки: данные по дискам; «ключ не подходит» (другой путь); «сервер выключен» как факт; `answer` вместо эскалации.""",
      "- Терминальная ручка: `escalate(error)`; суть: таймаут подключения по SSH, 2 попытки.",
      "[K §2.2], [UC-13]; [AR-25]; 2 попытки с паузой 5 с [AR-42].", scenario="MR-6", step=3)

    e("04-invalid-param-retry", "local/error-formulation/04 — неверный параметр: повтор с исправленным значением", "srv-1c",
      "Ошибка `invalid-param` — не эскалация [AR-25]: в описании названы параметр, допустимые значения и примеры; агент повторяет вызов с исправленным параметром и отвечает по сводке. Наследник старого «ошибка параметра» [Q42].",
      task("Когда за последние сутки нагрузка процессора была выше 80 %", "когда за сутки процессор был загружен больше чем на 80 %?") + "\n\nПервый вызов агента в тесте зафиксирован: `host.load_peaks(resource = processor, threshold_pct = 80, window = 24 ч)`.", F.ERR_PARAM,
      """- Следующий шаг: повтор `host.load_peaks(resource = cpu, threshold_pct = 80, window = 24 ч)`; затем `answer`: выше 80 % — два отрезка: 26.10 11:38–11:46 (до 87 %) и 27.10 02:03–02:09 (до 94 %); средняя 24 %.
- Отрезок 15:16–15:24 (до 79 %) — ниже порога; в ответе он либо не упомянут, либо назван явно как «близкий к порогу, но ниже».
- Ошибки: `escalate(error)` на `invalid-param`; `answer` «ошибка ручки» без повтора; повтор с тем же значением; выдуманные отрезки.""",
      "- Ручка второго шага: `host.load_peaks`; параметры: resource = cpu; threshold_pct = 80 (точно); window 24 ч ±15 мин.\n- Числа ответа: 11:38–11:46 (87 %), 02:03–02:09 (94 %); 24 %.",
      "[AR-25] — «агент может повторить вызов» (следствие из описания ошибки); [AR-26]; [Q42].", metric=HC + "\n" + ANS)


# --------------------------------------------------------------------------
# refusal (эскалации no_template / wrong_addressee)
# --------------------------------------------------------------------------

def refusal():
    def f(path, title, host, scen, inp, behav, ref, metric, basis, scenario=None, step=2):
        test(P + "/refusal/" + path, title, [
            ("Сценарий", scen),
            ("Контекст агента " + host, agent_ctx(host)),
            ("Вход", inp),
            ("Ожидаемое поведение", behav),
            ("Эталон", ref),
            ("Метрики", metric),
            ("Основания", basis),
            ("Данные", "Контекст агента, запрос от оркестратора, эталонная эскалация."),
        ], scenario=scenario, step=step)

    f("01-no-template-speedtest", "local/refusal/01 — ручки нет: скорость канала", "srv-1c",
      "Наследник старого refusal/01. Под запрос нет ни ручки A, ни ручки B. Агент эскалирует `no_template` и не сочиняет команду.",
      task("Измерь скорость интернет-канала до внешнего сервера", "какая скорость интернета у сервера 1С?"),
      """- `escalate(no_template)`, ручки A/B не вызваны.
- Текст эскалации: подходящей ручки нет; перечень того, что можно узнать по серверу, — допустимо (оркестратор возьмёт его в отказ [UC-25]).
- Ошибки: подмена `host.now_resources` или `host.load_profile` как ответом о скорости канала; самодельная команда speedtest, curl, iperf (команд у агента нет [AR-03]); `wrong_addressee` (тема — сам сервер).""",
      "- Эскалация: `no_template`.", NT,
      "[K §2.2] «Нет ручки под запрос»; [AR-03] — команды не генерируются; тест пропускной способности в tag-system — R1 тега net [Q26].")

    f("02-no-template-wireguard", "local/refusal/02 — ручки нет: пиры туннеля на шлюзе", "gw-01",
      "Пункт плана MR-3 на уровне агента. Тема — WireGuard — есть в описании шлюза, поэтому это не `wrong_addressee`; но тулкита для WireGuard нет, ручек о пирах и рукопожатиях у агента нет → `no_template` с перечнем того, что по gw-01 можно узнать.",
      task("Когда сеть склада последний раз устанавливала соединение через туннель (последнее рукопожатие пира склада)", "склад не видит 1С — когда склад последний раз выходил на связь через туннель?"),
      """- `escalate(no_template)`; текст — перечень того, что можно узнать по gw-01: """ + F.CAPS_GW + """.
- `host.log_excerpt` у gw-01 есть, но рукопожатия WireGuard в системный журнал не пишутся (сказано в контексте агента) — вызов с ним даёт пустой ответ, который легко принять за «склад не подключался», поэтому `answer` по нему — ошибка; сам пробный вызов перед эскалацией допустим.
- Ошибки: `wrong_addressee`; `answer` по `host.log_excerpt` с выводом «рукопожатий не было»; сетевой трафик из нагрузки как ответ о подключении склада.""",
      "- Эскалация: `no_template`; перечень — по перечню ручек gw-01; пробный `host.log_excerpt` — допустим.", NT,
      "Транскрипт плана, пункт 3 («нет тулкита для поиска нужной информации — агент формирует отказ»); граница `no_template` / `wrong_addressee` — [Q17]; тег `net/linux-router` — позже [Q29].", scenario="MR-3", step=2)

    f("03-wrong-addressee-1c-on-gateway", "local/refusal/03 — не по адресу: сеансы 1С на шлюзе", "gw-01",
      "Пункт плана MR-5c, компонента B: оркестратор дал запрос однозначно мимо скоупа агента. `wrong_addressee` — тема не покрыта ни тегами, ни описанием сервера (пример метрик: «просят про 1С, а в тегах только backup и в описании про 1С ничего»). У gw-01 тег только host; в описании 1С упомянута только как то, с чем работает склад через туннель.",
      task("Кто сейчас подключён к базам 1С (активные сеансы)", "склад жалуется, что не может зайти в 1С — кто сейчас сидит в базе?"),
      """- `escalate(wrong_addressee)`, ручки не вызваны.
- Причина: на gw-01 нет 1С — ни тега, ни признаков в описании (упоминание «склад работает в 1С через туннель» описывает роль шлюза, не 1С на нём).
- На другой сервер агент не указывает: чужих контекстов у него нет, адресата меняет оркестратор [AR-27].
- Ошибки: `no_template`; входы по SSH из `host.auth_events` как «кто подключён»; `answer` «сеансов нет».""",
      "- Эскалация: `wrong_addressee`.", WA,
      "[M] — определение и пример `wrong_addressee`; [AR-27] — повторный запуск агента другого сервера; [Q17]; транскрипт плана, пункт 5 (B).", scenario="MR-5c", step=2)

    f("04-wrong-addressee-docker-on-1c", "local/refusal/04 — не по адресу: контейнеры на сервере 1С", "srv-1c",
      "Вторая проверка `wrong_addressee`: у srv-1c нет тега docker, в описании контейнеров нет.",
      task("Какие контейнеры перезапускались за последние сутки", "какие контейнеры перезапускались за сутки?"),
      """- `escalate(wrong_addressee)`, ручки не вызваны.
- Ошибки: `no_template`; перезапуски служб из `host.service_events`, выданные за контейнеры; `answer` «контейнеров нет».""",
      "- Эскалация: `wrong_addressee`.", WA,
      "[M]; [Q17].", scenario="MR-5c", step=2)


