def limits():
    test(P + "/limits/01-handle-limit-exhausted", "local/limits/01 — лимит ручек на запуск исчерпан", [
        ("Сценарий", "Вне плана (X-LIM): ≤ 20 ручек на запуск [AR-32]; вызов сверх лимита отклоняется с комментарием, агенту остаётся терминальная ручка; 10 отклонённых вызовов подряд — система закрывает сессию, принудительной эскалации нет [AR-43]. Ожидается, что агент сам ответит оркестратору тем, что собрал, и скажет, чего не хватило, — не будет повторять вызовы."),
        ("Контекст агента srv-1c", agent_ctx("srv-1c") + "\n\nОстаток лимита ручек: 0 из 20."),
        ("Вход", task("Задания планировщика за 7 суток: по каждому заданию — расписание, запуски, ошибки и хвост вывода", "что у нас с заданиями планировщика на сервере 1С?") + "\n\nИстория запуска в тесте зафиксирована: `host.sched_jobs(window = 7 суток)` → сводка по 11 заданиям (как в orchestrator/report/15); затем 19 вызовов `host.log_excerpt` по журналам отдельных заданий (хвосты вывода получены для 9 из 11 заданий); 21-й вызов `host.log_excerpt(…)` — отказ системы: «лимит ручек (20) исчерпан»."),
        ("Ожидаемое поведение", """- `answer` с тем, что собрано: сводка по 11 заданиям (единственный сбой — pg_reindex.sh 24.10 04:00), хвосты вывода по 9 заданиям; явно сказано, что по 2 заданиям хвосты не получены — лимит обращений к серверу в этом запуске исчерпан.
- Ошибки: повторные вызовы ручек после отказа; `escalate(error)` без собранных данных; ответ «по всем 11» без оговорки; зависание без терминальной ручки."""),
        ("Эталон", "- Терминальная ручка: `answer`; в ответе упомянуты неполные данные (2 задания) из-за лимита."),
        ("Метрики", "- Rule-based `[предл.]` — вне долей v0.2: терминальная ручка вызвана; ручки A/B после отказа системы не вызываются.\n" + ANS),
        ("Основания", "[AR-32] — лимит 20, модель видит остаток; [AR-43] — механика исчерпания; выбор терминальной ручки после отказа — поведение модели, эталон — предложение тестов."),
        ("Данные", "Контекст агента с остатком лимита, запрос, история вызовов и отказ системы, эталон."),
    ], scenario="X-LIM")


if __name__ == "__main__":
    handle_choice()
    answer_from_return()
    error_formulation()
    refusal()
    limits()
    print("main local: ok")
